"""Graph traversal — BFS and DFS contain visited-set bugs."""
from collections import deque
from typing import Optional


class Graph:
    def __init__(self):
        self._adj: dict[str, list[str]] = {}

    def add_edge(self, u: str, v: str) -> None:
        """Add undirected edge."""
        self._adj.setdefault(u, []).append(v)
        self._adj.setdefault(v, []).append(u)

    def bfs(self, start: str) -> list[str]:
        """Return nodes in BFS order starting from start."""
        if start not in self._adj:
            return [start]
        visited = set()
        queue = deque([start])
        result = []
        while queue:
            node = queue.popleft()
            if node in visited:
                continue
            result.append(node)
            # BUG: adds to visited AFTER appending, but also needs to add
            # neighbors to visited before enqueuing to avoid duplicates in queue
            visited.add(node)
            for neighbor in self._adj.get(node, []):
                # BUG: should check 'if neighbor not in visited' before appending
                queue.append(neighbor)
        return result

    def dfs(self, start: str) -> list[str]:
        """Return nodes in DFS order starting from start."""
        if start not in self._adj:
            return [start]
        # BUG: visited initialized outside recursive helper but not passed
        result = []
        def _dfs(node):
            # BUG: missing visited set — will loop forever on cycles
            result.append(node)
            for neighbor in self._adj.get(node, []):
                _dfs(neighbor)
        _dfs(start)
        return result

    def has_path(self, src: str, dst: str) -> bool:
        """Return True if a path exists from src to dst."""
        raise NotImplementedError
